    // ---- Help Assistant (spec: must follow selected language) ----
    "help.title": "Help Assistant",
    "help.subtitle": "Tells you what every part of CareLink does",
    "help.inputPlaceholder": "Ask how CareLink works…",
    "help.backAria": "Back",
    "help.welcome":
      "Hello! I'm the CareLink guide. I can explain how the app works — patient registration, doctor login, the Care Link intake, document scanning, the AI summary, languages and themes. Just ask me anything like \"What does the app do?\".",
    "help.answer.register":
      "CareLink is a patient case-taking app. To get started, a patient enters their mobile number, verifies it with a 6-digit OTP, then registers by entering their name, basic health details and consent. Once registered, they get a private health record with a profile, timeline, documents and more.",
    "help.answer.doctor":
      "Doctors sign in with the Doctor ID and password issued by their hospital — not by mobile OTP. First-time doctors complete a short registration (identity, hospital credentials, professional details, consent) before entering the doctor dashboard. There they can review patient cases, the priority queue and clinical notes.",
    "help.answer.intake":
      "The Care Link intake is a self-service terminal in the hospital. A patient identifies themselves, gives consent, then answers a guided clinical-history questionnaire (voice, text or typing). Documents can be scanned/OCRed. The AI drafts a source-traceable clinical summary with red-flag alerts, which the doctor then verifies.",
    "help.answer.timeline":
      "The Health Timeline shows a patient's visits, documents, medications, lab reports and vaccines in one scroll, grouped by year. Filters let you narrow by Visit, Document, Medication, Report or Vaccine.",
    "help.answer.documents":
      "Patients can upload or scan prescription images, lab reports and discharge summaries. OCR reads the text and CareLink extracts fields like medicine name, dosage, date and the hospital, adding them to the health record.",
    "help.answer.language":
      "CareLink supports multiple languages including English, Hindi and Urdu. Urdu also switches the layout to right-to-left (RTL). You can change the language anytime from the Language screen on the welcome page.",
    "help.answer.theme":
      "The Accessibility screen lets you pick a theme colour — White, Blue, Green, Pink, Golden Yellow or Black. The whole app updates instantly. You can reach it from the Accessibility button on the welcome page.",
    "help.answer.ai":
      "I am the CareLink assistant. CareLink is an AI-assisted, source-traceable clinical history and case-taking app for hospitals and clinics. Its main parts are: Patient registration & profile, Doctor login with hospital-issued credentials, the Care Link intake self-service case-taking terminal, AI-drafted clinical summaries with red-flag detection, document OCR, a health timeline, language/accessibility themes and an ABDM/consent-ready design. Ask me about any of these and I'll explain them.",
    "help.suggest.1": "What does the app do?",
    "help.suggest.2": "How do patients register?",
    "help.suggest.3": "How does a doctor login?",
    "help.suggest.4": "What is the Care Link intake?",
    "help.suggest.5": "How does document scanning work?",

