    // ---- Help Assistant ----
    "help.title": "सहायता सहायक",
    "help.subtitle": "केयरलिंक के हर भाग के बारे में बताता है",
    "help.inputPlaceholder": "पूछें कि केयरलिंक कैसे काम करता है…",
    "help.backAria": "वापस",
    "help.welcome":
      "नमस्ते! मैं केयरलिंक का मार्गदर्शक हूँ। मैं बता सकता हूँ कि ऐप कैसे काम करता है — रोगी पंजीकरण, डॉक्टर लॉगिन, केयर लिंक कियोस्क, दस्तावेज़ स्कैनिंग, AI सारांश, भाषाएँ और थीम। बस \"ऐप क्या करता है?\" जैसा कुछ भी पूछिए।",
    "help.answer.register":
      "केयरलिंक एक रोगी केस-लेने वाला ऐप है। शुरू करने के लिए, रोगी अपना मोबाइल नंबर दर्ज करता है, 6 अंकों के OTP से सत्यापन करता है, फिर अपना नाम, बुनियादी स्वास्थ्य विवरण और सहमति दर्ज करके पंजीकरण करता है। पंजीकरण के बाद उन्हें प्रोफ़ाइल, टाइमलाइन, दस्तावेज़ आदि के साथ एक निजी स्वास्थ्य रिकॉर्ड मिलता है।",
    "help.answer.doctor":
      "डॉक्टर अपने अस्पताल द्वारा जारी डॉक्टर ID और पासवर्ड से लॉगिन करते हैं — मोबाइल OTP से नहीं। पहली बार के डॉक्टर डॉक्टर डैशबोर्ड में प्रवेश करने से पहले एक छोटा पंजीकरण (पहचान, अस्पताल प्रमाण-पत्र, पेशेवर विवरण, सहमति) पूरा करते हैं। वहाँ वे रोगी केस, प्राथमिकता कतार और क्लिनिकल नोट्स की समीक्षा कर सकते हैं।",
    "help.answer.intake":
      "केयर लिंक कियोस्क अस्पताल में एक स्व-सेवा टर्मिनल है। रोगी अपनी पहचान देता है, सहमति देता है, फिर एक निर्देशित क्लिनिकल-इतिहास प्रश्नावली (आवाज़, पाठ या टाइपिंग) का उत्तर देता है। दस्तावेज़ स्कैन/OCR किए जा सकते हैं। AI एक खोजी-स्रोत वाला क्लिनिकल सारांश तैयार करता है, जिसे डॉक्टर फिर सत्यापित करता है।",
    "help.answer.timeline":
      "स्वास्थ्य टाइमलाइन रोगी के विज़िट, दस्तावेज़, दवाइयाँ, लैब रिपोर्ट और टीके एक ही स्क्रॉल में, वर्ष के अनुसार समूहित दिखाती है। फ़िल्टर से आप विज़िट, दस्तावेज़, दवा, रिपोर्ट या टीके के अनुसार कम कर सकते हैं।",
    "help.answer.documents":
      "रोगी प्रिस्क्रिप्शन छवियाँ, लैब रिपोर्ट और डिस्चार्ज सारांश अपलोड या स्कैन कर सकते हैं। OCR पाठ पढ़ता है और केयरलिंक दवा का नाम, मात्रा, तिथि और अस्पताल जैसे क्षेत्र निकालकर स्वास्थ्य रिकॉर्ड में जोड़ता है।",
    "help.answer.language":
      "केयरलिंक अंग्रेज़ी, हिंदी और उर्दू सहित कई भाषाओं का समर्थन करता है। उर्दू लेआउट को दाएँ-से-बाएँ (RTL) भी बदल देती है। आप वेलकम पेज पर भाषा स्क्रीन से कभी भी भाषा बदल सकते हैं।",
    "help.answer.theme":
      "एक्सेसिबिलिटी स्क्रीन आपको एक थीम रंग चुनने देती है — सफ़ेद, नीला, हरा, गुलाबी, सुनहरा पीला या काला। पूरा ऐप तुरंत अपडेट होता है। आप वेलकम पेज पर एक्सेसिबिलिटी बटन से उस तक पहुँच सकते हैं।",
    "help.answer.ai":
      "मैं केयरलिंक सहायक हूँ। केयरलिंक एक AI-सहायक, खोजी-स्रोत वाला क्लिनिकल इतिहास और केस-लेने वाला ऐप है जो अस्पतालों और क्लीनिकों के लिए है। इसके मुख्य भाग हैं: रोगी पंजीकरण और प्रोफ़ाइल, अस्पताल-जारी प्रमाण-पत्रों के साथ डॉक्टर लॉगिन, केयर लिंक कियोस्क स्व-सेवा केस-लेने वाला टर्मिनल, रेड-फ़्लैग पहचान के साथ AI-निर्मित क्लिनिकल सारांश, दस्तावेज़ OCR, स्वास्थ्य टाइमलाइन, भाषा/एक्सेसिबिलिटी थीम और ABDM/सहमति-तैयार डिज़ाइन। इनके बारे में कुछ भी पूछिए, मैं समझाऊँगा।",
    "help.suggest.1": "ऐप क्या करता है?",
    "help.suggest.2": "रोगी कैसे पंजीकरण करते हैं?",
    "help.suggest.3": "डॉक्टर कैसे लॉगिन करता है?",
