    // ---- Help Assistant ----
    "help.title": "مدد ساتھی",
    "help.subtitle": "کیئرلنک کے ہر حصے کے بارے میں بتاتا ہے",
    "help.inputPlaceholder": "پوچھیں کہ کیئرلنک کیسے کام کرتا ہے…",
    "help.backAria": "واپس",
    "help.welcome":
      "ہیلو! میں کیئرلنک کا رہنما ہوں۔ میں بتا سکتا ہوں کہ ایپ کیسے کام کرتی ہے — مریض کا اندراج، ڈاکٹر کا لاگ ان، Care Link کیوسک، دستاویز اسکیننگ، AI خلاصہ، زبانیں اور تھیمز۔ بس مجھ سے کچھ پوچھیں جیسے \"ایپ کیا کرتی ہے؟\"۔",
    "help.answer.register":
      "کیئرلنک ایک مریض کیس لینے والی ایپ ہے۔ شروع کرنے کے لیے، مریض اپنا موبائل نمبر درج کرتا ہے، 6 ہندسوں کے OTP سے تصدیق کرتا ہے، پھر اپنا نام، بنیادی صحت کی تفصیلات اور رضامندی درج کر کے اندراج مکمل کرتا ہے۔ اندراج کے بعد انہیں ایک نجی صحت ریکارڈ ملتا ہے جس میں پروفائل، ٹائم لائن، دستاویزات وغیرہ شامل ہیں۔",
    "help.answer.doctor":
      "ڈاکٹر اپنے ہسپتال کی جاری کردہ ڈاکٹر آئی ڈی اور پاس ورڈ سے لاگ ان کرتے ہیں — موبائل OTP سے نہیں۔ پہلی بار ڈاکٹر ڈیش بورڈ میں داخل ہونے سے پہلے ایک مختصر اندراج (شناخت، ہسپتال کی اسناد، پیشہ ورانہ تفصیلات، رضامندی) مکمل کرتے ہیں۔ وہاں وہ مریض کے کیس، ترجیحی قطار اور طبی نوٹس کا جائزہ لے سکتے ہیں۔",
    "help.answer.intake":
      "Care Link کیوسک ہسپتال میں ایک خود خدمت ٹرمینل ہے۔ مریض اپنی شناخت دیتا ہے، رضامندی دیتا ہے، پھر ایک رہنمائی شدہ طبی تاریخ کے سوالنامے (آواز، متن یا ٹائپنگ) کے جواب دیتا ہے۔ دستاویزات اسکین/OCR کی جا سکتی ہیں۔ AI ایک ماخذ سے قابلِ تعقیب طبی خلاصہ تیار کرتا ہے، جسے ڈاکٹر پھر تصدیق کرتا ہے۔",
    "help.answer.timeline":
      "صحت کی ٹائم لائن مریض کے دوروں، دستاویزات، ادویات، لیب رپورٹس اور ویکسینز کو ایک اسکرول میں، سال کے لحاظ سے گروہ بندی کر کے دکھاتی ہے۔ فلٹرز آپ کو دورہ، دستاویز، دوا، رپورٹ یا ویکسین کے مطابق محدود کرنے دیتے ہیں۔",
    "help.answer.documents":
      "مریض نسخے کی تصاویر، لیب رپورٹس اور ڈسچارج خلاصے اپ لوڈ یا اسکین کر سکتے ہیں۔ OCR متن پڑھتا ہے اور کیئرلنک دوا کا نام، خوراک، تاریخ اور ہسپتال جیسے شعبے نکال کر صحت ریکارڈ میں شامل کرتا ہے۔",
    "help.answer.language":
      "کیئرلنک انگریزی، ہندی اور اردو سمیت متعدد زبانوں کی حمایت کرتا ہے۔ اردو ترتیب کو دائیں سے بائیں (RTL) بھی بدل دیتی ہے۔ آپ خوش آمدید صفحہ پر زبان کی اسکرین سے کسی بھی وقت زبان بدل سکتے ہیں۔",
    "help.answer.theme":
      "رسائی اسکرین آپ کو ایک تھیم رنگ منتخب کرنے دیتی ہے — سفید، نیلا، سبز، گلابی، سنہری پیلا یا سیاہ۔ پوری ایپ فوری طور پر اپ ڈیٹ ہوتی ہے۔ آپ خوش آمدید صفحہ پر رسائی کے بٹن سے اس تک پہنچ سکتے ہیں۔",
    "help.answer.ai":
      "میں کیئرلنک مددگار ہوں۔ کیئرلنک ایک AI-تعاون یافتہ، ماخذ سے قابلِ تعقیب طبی تاریخ اور کیس لینے والی ایپ ہے جو ہسپتالوں اور کلینکس کے لیے ہے۔ اس کے اہم حصے ہیں: مریض اندراج اور پروفائل، ہسپتال کی جاری کردہ اسناد کے ساتھ ڈاکٹر لاگ ان، Care Link کیوسک خود خدمت کیس لینے والا ٹرمینل، سرخ جھنڈوں کی نشاندہی کے ساتھ AI سے تیار کردہ طبی خلاصہ، دستاویز OCR، صحت کی ٹائم لائن، زبان/رسائی تھیمز اور ABDM/رضامندی کے لیے تیار ڈیزائن۔ ان میں سے کسی کے بارے میں پوچھیں، میں سمجھا دوں گا۔",
