    "help.title": "সহায়তা সহকারী",
    "help.subtitle": "কেয়ারলিংকের প্রতিটি অংশ কী করে তা বলে",
    "help.inputPlaceholder": "জিজ্ঞাসা করুন কেয়ারলিংক কীভাবে কাজ করে…",
    "help.backAria": "পেছনে",
    "help.welcome": "হ্যালো! আমি কেয়ারলিংকের গাইড। আমি ব্যাখ্যা করতে পারি অ্যাপটি কীভাবে কাজ করে — রোগী নিবন্ধন, ডাক্তার লগইন, কেয়ার লিংক কিয়স্ক, নথি স্ক্যানিং, AI সারাংশ, ভাষা ও থিম। শুধু আমার কাছে \"অ্যাপটি কী করে?\" এর মতো যেকোনো প্রশ্ন করুন।",
    "help.answer.register": "কেয়ারলিংক একটি রোগীর কেস-গ্রহণকারী অ্যাপ। শুরু করতে, রোগী তার মোবাইল নম্বর লিখে, ৬ ডিজিটের OTP দিয়ে যাচাই করে, তারপর নাম, মৌলিক স্বাস্থ্য বিবরণ ও সম্মতি দিয়ে নিবন্ধন করে। নিবন্ধনের পর তারা প্রোফাইল, সময়রেখা, নথি ইত্যাদি সহ একটি ব্যক্তিগত স্বাস্থ্য রেকর্ড পায়।",
    "help.answer.doctor": "ডাক্তাররা তাদের হাসপাতাল জারি করা ডাক্তার আইডি ও পাসওয়ার্ড দিয়ে সাইন ইন করেন — মোবাইল OTP দিয়ে নয়। প্রথমবারের ডাক্তাররা ডাক্তার ড্যাশবোর্ডে প্রবেশের আগে একটি ছোট নিবন্ধন (পরিচয়, হাসপাতাল প্রমাণপত্র, পেশাদার বিবরণ, সম্মতি) সম্পন্ন করেন। সেখানে তারা রোগীর কেস, অগ্রাধিকার সারি ও ক্লিনিক্যাল নোট পর্যালোচনা করতে পারেন।",
    "help.answer.intake": "কেয়ার লিংক কিয়স্ক হাসপাতালের একটি স্ব-সেবা টার্মিনাল। রোগী নিজের পরিচয় দেয়, সম্মতি দেয়, তারপর একটি নির্দেশিত ক্লিনিক্যাল-ইতিহাস প্রশ্নমালার উত্তর দেয় (ভয়েস, টেক্সট বা টাইপিং)। নথি স্ক্যান/OCR করা যায়। AI একটি উৎস-সনাক্তযোগ্য ক্লিনিক্যাল সারাংশ তৈরি করে যার রেড-ফ্ল্যাগ সতর্কতা থাকে, যা ডাক্তার পরে যাচাই করেন।",
    "help.answer.timeline": "স্বাস্থ্য সময়রেখা রোগীর দর্শন, নথি, ওষুধ, ল্যাব রিপোর্ট ও টিকা এক স্ক্রলে, বছর অনুযায়ী গোষ্ঠীভুক্ত দেখায়। ফিল্টার দিয়ে আপনি দর্শন, নথি, ওষুধ, রিপোর্ট বা টিকা অনুসারে সংকীর্ণ করতে পারেন।",
    "help.answer.documents": "রোগীরা প্রেসক্রিপশন ছবি, ল্যাব রিপোর্ট ও ডিসচার্জ সারাংশ আপলোড বা স্ক্যান করতে পারেন। OCR লেখা পড়ে এবং কেয়ারলিংক ওষুধের নাম, ডোজ, তারিখ ও হাসপাতালের মতো ক্ষেত্র নিষ্কাশন করে স্বাস্থ্য রেকর্ডে যোগ করে।",
    "help.answer.language": "কেয়ারলিংক ইংরেজি, হিন্দি ও উর্দু সহ একাধিক ভাষা সমর্থন করে। উর্দু লেআউটকে ডান-থেকে-বামে (RTL)ও পরিবর্তন করে। আপনি ওয়েলকাম পেজের ভাষা স্ক্রিন থেকে যেকোনো সময় ভাষা পরিবর্তন করতে পারেন।",
    "help.answer.theme": "অভিগম্যতা স্ক্রিন আপনাকে একটি থিম রং বেছে নিতে দেয় — সাদা, নীল, সবুজ, গোলাপি, সোনালি হলুদ বা কালো। পুরো অ্যাপ অবিলম্বে আপডেট হয়। আপনি ওয়েলকাম পেজের অভিগম্যতা বাটন থেকে সেখানে পৌঁছাতে পারেন।",
    "help.answer.ai": "আমি কেয়ারলিংক সহকারী। কেয়ারলিংক একটি AI-সহায়ক, উৎস-সনাক্তযোগ্য ক্লিনিক্যাল ইতিহাস ও কেস-গ্রহণকারী অ্যাপ যা হাসপাতাল ও ক্লিনিকের জন্য। এর মূল অংশ: রোগী নিবন্ধন ও প্রোফাইল, হাসপাতাল-জারি প্রমাণপত্র দিয়ে ডাক্তার লগইন, কেয়ার লিংক কিয়স্ক স্ব-সেবা কেস-গ্রহণকারী টার্মিনাল, রেড-ফ্ল্যাগ সনাক্তকরণ সহ AI-নির্মিত ক্লিনিক্যাল সারাংশ, নথি OCR, স্বাস্থ্য সময়রেখা, ভাষা/অভিগম্যতা থিম এবং ABDM/সম্মতি-প্রস্তুত ডিজাইন। এগুলোর যেকোনো সম্পর্কে জিজ্ঞাসা করুন, আমি ব্যাখ্যা করব।",
    "help.suggest.1": "অ্যাপটি কী করে?",
    "help.suggest.2": "রোগীরা কীভাবে নিবন্ধন করে?",
    "help.suggest.3": "ডাক্তার কীভাবে লগইন করে?",
    "help.suggest.4": "কেয়ার লিংক কিয়স্ক কী?",
    "help.suggest.5": "নথি স্ক্যানিং কীভাবে কাজ করে?",

