    "intake.consentBody": "உங்கள் வரலாறு AI-உருவாக்கியது, நீங்கள் சொல்வது மற்றும் உங்கள் பதிவுகளிலிருந்து சுருக்கப்பட்டது. இது ஒருபோதும் நோயறிதல் அல்ல.",
