    "clinical.consentHeader": "சம்மதம் & தனியுரிமை",
    "clinical.consentProtected": "உங்கள் தரவு பாதுகாக்கப்படுகிறது",
    "clinical.consentBodyLong": "டிஜிட்டல் பெர்சனல் டேட்டா ப்ரொடெக்ஷன் சட்டம் 2023 மற்றும் ABDM சம்மத கட்டமைப்புடன் இணக்கமானது. நீங்கள் கட்டுப்பாட்டில் இருக்கிறீர்கள் — சம்மதம் எப்போது வேண்டுமானாலும் திரும்பப் பெறலாம், மேலும் சமர்ப்பித்த பிறகு தற்காலிக அமர்வுத் தரவு அழிக்கப்படும்.",
    "clinical.consentReview": "எங்களை என்ன செய்ய அனுமதிக்கிறீர்கள் என்பதை மதிப்பாய்வு செய்யவும்",
    "clinical.consentRevoke": "பிற்காலத்தில் அமைப்புகளில் எந்த அனுமதியையும் திரும்பப் பெறலாம்",
