    "clinical.pushHis": "மருத்துவமனை அமைப்புக்கு சுருக்கம் அனுப்பப்படுகிறது",
    "clinical.linkAbha": "ABHA சுகாதாரப் பதிவுடன் இணைக்கப்படுகிறது",
    "clinical.clearData": "தற்காலிக அமர்வுத் தரவு அழிக்கப்படுகிறது",
    "clinical.allSet": "அனைத்தும் தயார்!",
    "clinical.allSetBody": "உங்கள் மருத்துவ வரலாறு மற்றும் ஆவணங்கள் உங்கள் மருத்துவருக்கு அனுப்பப்பட்டுள்ளன. ஆலோசனை அறைக்குச் செல்லவும்.",
    "clinical.reference": "மருத்துவமனை குறிப்பு",
