    "clinical.sessionCleared": "அமர்வுத் தரவு அழிக்கப்பட்டது · சம்மதம் சேமிக்கப்பட்டது",
    "clinical.documentsDigitized": "ஆவணம்(கள்) டிஜிட்டல் மயமாக்கப்பட்டது",
    "clinical.priorityFlag": "முன்னுரிமை மதிப்பாய்வு கொடியிடப்பட்டது",
    "clinical.priorityBody": "உங்கள் வழக்கு அவசர கவனத்திற்காக கொடியிடப்பட்டுள்ளது. கவுன்டரில் இதைக் குறிப்பிடவும்.",
