    "clinical.flagTriage": "முன்னுரிமை பரிசோதனை பரிந்துரைக்கப்படுகிறது",
    "clinical.flagBody": " அவசர மதிப்பாய்வுக்காக கொடியிடப்பட்டது",
    "clinical.docsHeader": "ஆவண டிஜிட்டல்மயமாக்கல்",
    "clinical.docsStep": "படி 4 இல் 5",
