    "help.title": "సహాయ సహాయకుడు",
    "help.subtitle": "కేర్ లింక్ యొక్క ప్రతి భాగం ఏమి చేస్తుందో చెబుతుంది",
    "help.inputPlaceholder": "కేర్ లింక్ ఎలా పనిచేస్తుందో అడగండి…",
    "help.backAria": "వెనుకకు",
    "help.welcome": "హలో! నేను కేర్ లింక్ యొక్క గైడ్. యాప్ ఎలా పనిచేస్తుందో వివరించగలను — రోగి నమోదు, వైద్యుడు లాగిన్, కేర్ లింక్ కియోస్క్, పత్ర స్కానింగ్, AI సారాంశం, భాషలు మరియు థీమ్‌లు. \"యాప్ ఏమి చేస్తుంది?\" వంటి ఏదైనా నన్ను అడగండి.",
    "help.answer.register": "కేర్ లింక్ ఒక రోగి కేసు-తీసుకునే యాప్. ప్రారంభించడానికి, రోగి తన మొబైల్ నంబర్‌ను నమోదు చేసి, 6 అంకెల OTP తో ధృవీకరించి, తర్వాత పేరు, మూల ఆరోగ్య వివరాలు మరియు సమ్మతి నమోదు చేసి నమోదు చేస్తారు. నమోదు చేసిన తర్వాత వారికి ప్రొఫైల్, కాలరేఖ, పత్రాలు మరియు మరిన్నింటితో ప్రైవేట్ ఆరోగ్య రికార్డు లభిస్తుంది.",
    "help.answer.doctor": "వైద్యులు తమ ఆసుపత్రి జారీ చేసిన వైద్యుడు ID మరియు పాస్‌వర్డ్‌తో సైన్ ఇన్ చేస్తారు — మొబైల్ OTP తో కాదు. మొదటిసారి వైద్యులు వైద్యుడి డాష్‌బోర్డ్‌లోకి ప్రవేశించే ముందు చిన్న నమోదు (గుర్తింపు, ఆసుపత్రి ఆధారాలు, ప్రొఫెషనల్ వివరాలు, సమ్మతి) పూర్తి చేస్తారు. అక్కడ వారు రోగి కేసులు, ప్రాధాన్యత క్యూ మరియు క్లినికల్ నోట్స్‌ను సమీక్షించవచ్చు.",
    "help.answer.intake": "కేర్ లింక్ కియోస్క్ ఆసుపత్రిలో స్వీయ-సేవ టెర్మినల్. రోగి తనను గుర్తించి, సమ్మతి ఇచ్చి, తర్వాత మార్గనిర్దేశిక క్లినికల్-చరిత్ర ప్రశ్నపత్రానికి (వాయిస్, టెక్స్ట్ లేదా టైపింగ్) సమాధానం ఇస్తారు. పత్రాలను స్కాన్/OCR చేయవచ్చు. AI రెడ్-ఫ్లాగ్ హెచ్చరికలతో మూల-గుర్తించగల క్లినికల్ సారాంశాన్ని రూపొందిస్తుంది, దీనిని వైద్యుడు తర్వాత ధృవీకరిస్తారు.",
    "help.answer.timeline": "ఆరోగ్య కాలరేఖ రోగి యొక్క సందర్శనలు, పత్రాలు, మందులు, ల్యాబ్ రిపోర్టులు మరియు టీకాలను ఒక స్క్రోల్‌లో, సంవత్సరం ద్వారా సమూహంగా చూపుతుంది. సందర్శన, పత్రం, మందు, రిపోర్టు లేదా టీకా ద్వారా ఫిల్టర్‌లు కుదించడానికి వీలు కల్పిస్తాయి.",
    "help.answer.documents": "రోగులు ప్రిస్క్రిప్షన్ చిత్రాలు, ల్యాబ్ రిపోర్టులు మరియు డిస్చార్జ్ సారాంశాలను అప్‌లోడ్ లేదా స్కాన్ చేయవచ్చు. OCR టెక్స్ట్‌ను చదువుతుంది మరియు కేర్ లింక్ మందు పేరు, మోతాదు, తేదీ మరియు ఆసుపత్రి వంటి ఫీల్డ్‌లను సంగ్రహించి ఆరోగ్య రికార్డుకు జోడిస్తుంది.",
    "help.answer.language": "కేర్ లింక్ ఆంగ్లం, హిందీ మరియు ఉర్దూతో సహా బహుళ భాషలకు మద్దతు ఇస్తుంది. ఉర్దూ లేఅవుట్‌ను కుడి-నుండి-ఎడమకు (RTL) కూడా మారుస్తుంది. స్వాగత పేజీలోని భాషా స్క్రీన్ నుండి మీరు ఎప్పుడైనా భాషను మార్చవచ్చు.",
    "help.answer.theme": "యాక్సెసిబిలిటీ స్క్రీన్ మిమ్మల్ని థీమ్ రంగు ఎంచుకోవడానికి అనుమతిస్తుంది — తెలుపు, నీలం, ఆకుపచ్చ, గులాబీ, బంగారు పసుపు లేదా నలుపు. మొత్తం యాప్ వెంటనే అప్‌డేట్ అవుతుంది. స్వాగత పేజీలోని యాక్సెసిబిలిటీ బటన్ నుండి మీరు దానిని చేరుకోవచ్చు.",
    "help.answer.ai": "నేను కేర్ లింక్ సహాయకుడిని. కేర్ లింక్ అనేది ఆసుపత్రులు మరియు క్లినిక్‌ల కోసం AI-సహాయక, మూల-గుర్తించగల క్లినికల్ చరిత్ర మరియు కేసు-తీసుకునే యాప్. దాని ప్రధాన భాగాలు: రోగి నమోదు & ప్రొఫైల్, ఆసుపత్రి జారీ చేసిన ఆధారాలతో వైద్యుడు లాగిన్, కేర్ లింక్ కియోస్క్ స్వీయ-సేవ కేసు-తీసుకునే టెర్మినల్, రెడ్-ఫ్లాగ్ గుర్తింపుతో AI-సృష్టించిన క్లినికల్ సారాంశాలు, పత్రం OCR, ఆరోగ్య కాలరేఖ, భాష/యాక్సెసిబిలిటీ థీమ్‌లు మరియు ABDM/సమ్మతి-సిద్ధంగా ఉన్న డిజైన్. వీటిలో దేని గురించైనా అడగండి, నేను వివరిస్తాను.",
    "help.suggest.1": "యాప్ ఏమి చేస్తుంది?",
    "help.suggest.2": "రోగులు ఎలా నమోదు చేసుకుంటారు?",
    "help.suggest.3": "వైద్యుడు ఎలా లాగిన్ అవుతారు?",
    "help.suggest.4": "కేర్ లింక్ కియోస్క్ అంటే ఏమిటి?",
    "help.suggest.5": "పత్ర స్కానింగ్ ఎలా పని చేస్తుంది?",

