    "ai.subtitle": "మీ ఆన్‌బోర్డింగ్ వాయిస్ అసిస్టెంట్",
    "ai.welcome":
      "హలో! నేను కేర్ లింక్ AI, మీ ఆన్‌బోర్డింగ్ సహాయకుడిని. రోగి నమోదు ప్రారంభించడం, వైద్యుడిగా చేరడం, భాష మార్చడం లేదా హెల్ప్ డెస్క్ తెరవడం కోసం నన్ను అడగండి.",
    "ai.inputPlaceholder": "నన్ను ఏదైనా అడగండి…",
    "ai.sendAria": "పంపు",
    "ai.micAria": "మాట్లాడండి",
    "ai.backAria": "వెనుక",
