    "help.title": "मदत सहाय्यक",
    "help.subtitle": "केअर लिंकच्या प्रत्येक भागाचे स्पष्टीकरण",
    "help.inputPlaceholder": "केअर लिंक कसे कार्य करते ते विचारा…",
    "help.backAria": "मागे",
    "help.welcome": "नमस्कार! मी केअर लिंकचा मार्गदर्शक. या अ‍ॅपवरील आरोग्य रेकॉर्ड, कागदपत्रे, डॉक्टर लॉगिन, मेडीकिओस्क, AI सारांश, भाषा आणि थीम यासारख्या सर्व गोष्टी मी समजावू शकतो. \"हे अ‍ॅप काय करते?\" असे काहीही मला विचारा.",
    "help.answer.register": "केअर लिंक हे एक रुग्ण केस-टेकिंग ॲप आहे. सुरू करण्यासाठी रुग्ण आपला मोबाईल नंबर टाकतो, OTP ने पडताळतो, नंतर पूर्ण नाव, मूलभूत आरोग्य तपशील व संमती नोंदवतो. नोंदणीनंतर त्यांना प्रोफाइल, कालरेषा, कागदपत्रे इत्यादीसह निजी आरोग्य रेकॉर्ड मिळते.",
    "help.answer.doctor": "डॉक्टर आपल्या रुग्णालयाने दिलेल्या डॉक्टर ID व पासवर्डने साइन इन करतात — मोबाईल OTP ने नाही. पहिल्यांदा डॉक्टर डॅशबोर्डमध्ये प्रवेश करण्यापूर्वी लहान नोंदणी (ओळख, रुग्णालय आधार, व्यावसायिक तपशील, संमती) पूर्ण करतात. तेथे ते रुग्ण केस, प्राधान्य रांग व क्लिनिकल टीपा पडताळतात.",
    "help.answer.intake": "मेडीकिओस्क हे रुग्णालयातील स्वयं-सेवा टर्मिनल आहे. रुग्ण स्वतःला ओळखतो, संमती देतो, नंतर मार्गदर्शित क्लिनिकल-इतिहास प्रश्नावली (आवाज/टेक्स्ट/टायपिंग) भरतो. कागदपत्रे स्कॅन/OCR केली जातात. AI रेड-फ्लॅग सूचनांसह स्रोत-समर्थनीय क्लिनिकल सारांश तयार करतो, जो डॉक्टर नंतर पडताळतात.",
    "help.answer.timeline": "आरोग्य कालरेषा रुग्णाच्या भेटी, कागदपत्रे, औषधे, लॅब रिपोर्ट आणि लसी एका स्क्रोलमध्ये, वर्षानुसार गटांमध्ये दाखवते. भेट, कागदपत्र, औषध, रिपोर्ट किंवा लसीद्वारे फिल्टर आवश्यकतेनुसार कमी करतात.",
    "help.answer.documents": "रुग्ण प्रिस्क्रिप्शन प्रतिमा, लॅब रिपोर्ट आणि डिस्चार्ज सारांश अपलोड किंवा स्कॅन करू शकतात. OCR मजकूर वाचतो आणि केअर लिंक औषधाचे नाव, मात्रा, तारीख आणि रुग्णालय यासारखे फील्ड काढून आरोग्य रेकॉर्डमध्ये जोडतो.",
    "help.answer.language": "केअर लिंक इंग्रजी, हिंदी आणि उर्दूसह अनेक भाषांना समर्थन देते. उर्दू लेआउट उजवीकडून-डावीकडे (RTL) देखील वळवते. तुम्ही स्वागत पृष्ठावरील भाषा स्क्रीनवरून कधीही भाषा बदलू शकता.",
    "help.answer.theme": "प्रवेशयोग्यता स्क्रीन तुम्हाला थीम रंग निवडण्यास देते — पांढरा, निळा, हिरवा, गुलाबी, सोनेरी पिवळा किंवा काळा. संपूर्ण ॲप लगेच अद्यावत होते. तुम्ही स्वागत पृष्ठावरील प्रवेशयोग्यता बटनातून ते साधता.",
    "help.answer.ai": "मी केअर लिंक सहाय्यक आहे. केअर लिंक हे रुग्णालये व क्लिनिकसाठी AI-सहाय्य, स्रोत-समर्थनीय क्लिनिकल इतिहास आणि केस-टेकिंग ॲप आहे. त्याचे मुख्य घटक: रुग्ण नोंदणी आणि प्रोफाइल, रुग्णालय-दिलेल्या आधारांसह डॉक्टर लॉगिन, मेडीकिओस्क स्वयं-सेवा केस-टेकिंग टर्मिनल, रेड-फ्लॅग शोधासह AI-निर्मित क्लिनिकल सारांश, कागदपत्र OCR, आरोग्य कालरेषा, भाषा/प्रवेशयोग्यता थीम आणि ABDM/संमती-तयार डिझाइन. यापैकी कशाबद्दलही विचारा.",
    "help.suggest.1": "हे ॲप काय करते?",
