    "help.title": "મદદ સહાયક",
    "help.subtitle": "કેર લિંકના દરેક ભાગનું સમજૂતી",
    "help.inputPlaceholder": "કેર લિંક કેવી રીતે કામ કરે છે તે પૂછો…",
    "help.backAria": "પાછળ",
    "help.welcome": "નમસ્તે! હું કેર લિંકનો માર્ગદર્શક. આ એપ કેવી રીતે કામ કરે છે તે હું સમજાવી શકું છું — દર્દી નોંધણી, ડૉક્ટર લૉગિન, મેડિકિઓસ્ક, પત્ર સ્કેનિંગ, AI સારાંશ, ભાષાઓ અને થીમ. \"આ એપ શું કરે છે?\" એવું કંઈપણ મને પૂછો.",
    "help.answer.register": "કેર લિંક એ દર્દી કેસ-ટેકિંગ એપ છે. પ્રારંભ કરવા દર્દી પોતાનો મોબાઇલ નંબર દાખલ કરે છે, OTP દ્વારા ચકાસે છે, પછી પૂરું નામ, મૂળભૂત આરોગ્ય વિગતો અને સંમતિ નોંધાવે છે. નોંધણી પછી તેમને પ્રોફાઇલ, સમયરેખા, પત્રો વગેરે સાથે ખાનગી આરોગ્ય રેકોર્ડ મળે છે.",
    "help.answer.doctor": "ડૉક્ટર પોતાની હૉસ્પિટલે આપેલ ડૉક્ટર ID અને પાસવર્ડથી સાઇન ઇન કરે છે — મોબાઇલ OTP થી નહીં. પહેલીવાર ડૉક્ટર ડેશબોર્ડમાં પ્રવેશતા પહેલાં નાની નોંધણી (ઓળખ, હૉસ્પિટલ પ્રમાણપત્રો, વ્યાવસાયિક વિગતો, સંમતિ) પૂર્ણ કરે છે. ત્યાં તેઓ દર્દી કેસ, પ્રાધાન્ય કતાર અને ક્લિનિકલ નોંધોની સમીક્ષા કરી શકે છે.",
    "help.answer.intake": "મેડિકિઓસ્ક એ હૉસ્પિટલમાં સ્વ-સેવા ટર્મિનલ છે. દર્દી પોતાને ઓળખે છે, સંમતિ આપે છે, પછી માર્ગદર્શિત ક્લિનિકલ-ઇતિહાસ પ્રશ્નાવલી (અવાજ/ટેક્સ્ટ/ટાઇપિંગ) ભરે છે. પત્રો સ્કેન/OCR થાય છે. AI રેડ-ફ્લેગ ચેતવણીઓ સાથે સ્ત્રોત-સમર્થનીય ક્લિનિકલ સારાંશ બનાવે છે, જે ડૉક્ટર પછી ચકાસે છે.",
    "help.answer.timeline": "આરોગ્ય સમયરેખા દર્દીની ભેટો, પત્રો, દવાઓ, લેબ રિપોર્ટ અને રસીકરણ એક સ્ક્રોલમાં, વર્ષ દ્વારા જૂથમાં બતાવે છે. ભેટ, પત્ર, દવા, રિપોર્ટ અથવા રસી દ્વારા ફિલ્ટર સંકુચિત કરવાની મંજૂરી આપે છે.",
    "help.answer.documents": "દર્દી પ્રિસ્ક્રિપ્શન છબી, લેબ રિપોર્ટ અને ડિસ્ચાર્જ સારાંશ અપલોડ અથવા સ્કેન કરી શકે છે. OCR ટેક્સ્ટ વાંચે છે અને કેર લિંક દવાનું નામ, માત્રા, તારીખ અને હૉસ્પિટલ જેવા ફીલ્ડ કાઢીને આરોગ્ય રેકોર્ડમાં ઉમેરે છે.",
    "help.answer.language": "કેર લિંક અંગ્રેજી, હિંદી અને ઉર્દૂ સહિત અનેક ભાષાઓને સમર્થન આપે છે. ઉર્દૂ લેઆઉટને જમણે-થી-ડાબે (RTL) પણ ફેરવે છે. સ્વાગત પૃષ્ઠના ભાષા સ્ક્રીનથી કોઈપણ સમયે ભાષા બદલી શકો છો.",
    "help.answer.theme": "સુલભતા સ્ક્રીન તમને થીમ રંગ પસંદ કરવા દે — સફેદ, વાદળી, લીલો, ગુલાબી, સોનેરી પીળો અથવા કાળો. સમગ્ર એપ તરત અપડેટ થાય છે. સ્વાગત પૃષ્ઠના સુલભતા બટનથી તે મેળવી શકો છો.",
    "help.answer.ai": "હું કેર લિંક સહાયક છું. કેર લિંક એ હૉસ્પિટલ અને ક્લિનિક માટે AI-સહાયિત, સ્ત્રોત-સમર્થનીય ક્લિનિકલ ઇતિહાસ અને કેસ-ટેકિંગ એપ છે. તેના મુખ્ય ભાગો: દર્દી નોંધણી અને પ્રોફાઇલ, હૉસ્પિટલ-આપેલા પ્રમાણપત્રોથી ડૉક્ટર લૉગિન, મેડિકિઓસ્ક સ્વ-સેવા કેસ-ટેકિંગ ટર્મિનલ, રેડ-ફ્લેગ શોધ સાથે AI-બનાવેલ ક્લિનિકલ સારાંશ, પત્ર OCR, આરોગ્ય સમયરેખા, ભાષા/સુલભતા થીમ અને ABDM/સંમતિ-તૈયાર ડિઝાઇન. આમાંથી કોઈપણ પૂછો.",
    "help.suggest.1": "આ એપ શું કરે છે?",
    "help.suggest.2": "દર્દી કેવી રીતે નોંધણી કરે છે?",
    "help.suggest.3": "ડૉક્ટર કેવી રીતે લૉગિન કરે છે?",
    "help.suggest.4": "મેડિકિઓસ્ક શું છે?",
    "help.suggest.5": "પત્ર સ્કેનિંગ કેવી રીતે કામ કરે છે?",

    // ---- Startup AI Assistant ----
