    "clinical.flagBody": " ತುರ್ತು ಪರಿಶೀಲನೆಗಾಗಿ ಫ್ಲ್ಯಾಗ್ ಮಾಡಲಾಗಿದೆ",
    "clinical.docsHeader": "ಪತ್ರ ಡಿಜಿಟೈಜೇಶನ್",
