    "help.title": "ಸಹಾಯ ಸಹಾಯಕ",
    "help.subtitle": "ಕೇರ್ ಲಿಂಕ್‌ನ ಪ್ರತಿಯೊಂದು ಭಾಗದ ವಿವರಣೆ",
    "help.inputPlaceholder": "ಕೇರ್ ಲಿಂಕ್ ಹೇಗೆ ಕೆಲಸ ಮಾಡುತ್ತದೆ ಎಂದು ಕೇಳಿ…",
    "help.backAria": "ಹಿಂದೆ",
    "help.welcome": "ನಮಸ್ತೆ! ನಾನು ಕೇರ್ ಲಿಂಕ್‌ನ ಮಾರ್ಗದರ್ಶಿ. ಈ ಅಪ್ ಹೇಗೆ ಕೆಲಸ ಮಾಡುತ್ತದೆ ಎಂದು ವಿವರಿಸಬಲ್ಲೆ — ರೋಗಿ ನೋಂದಣಿ, ವೈದ್ಯ ಲಾಗಿನ್, ಮೆಡಿಕಿಯೋಸ್ಕ್, ಪತ್ರ ಸ್ಕ್ಯಾನಿಂಗ್, AI ಸಾರಾಂಶ, ಭಾಷೆಗಳು ಮತ್ತು ಥೀಮ್. \"ಈ ಅಪ್ ಏನು ಮಾಡುತ್ತದೆ?\" ಎಂದು ನನ್ನನ್ನು ಕೇಳಿ.",
    "help.answer.register": "ಕೇರ್ ಲಿಂಕ್ ಒಂದು ರೋಗಿ-ಸ್ವೀಕಾರ ಅಪ್. ಪ್ರಾರಂಭಿಸಲು ರೋಗಿ ತಮ್ಮ ಮೊಬೈಲ್ ಸಂಖ್ಯೆಯನ್ನು ನಮೂದಿಸುತ್ತಾರೆ, OTP ಯಿಂದ ಪರಿಶೀಲಿಸುತ್ತಾರೆ, ನಂತರ ಪೂರ್ಣ ಹೆಸರು, ಮೂಲ ಆರೋಗ್ಯ ವಿವರಗಳು ಮತ್ತು ಸಮ್ಮತಿಯನ್ನು ದಾಖಲಿಸುತ್ತಾರೆ. ದಾಖಲಾತಿಯ ನಂತರ ಅವರಿಗೆ ಪ್ರೊಫೈಲ್, ಸಮಯರೇಖೆ, ಪತ್ರಗಳು ಇತ್ಯಾದಿ ಹೊಂದಿರುವ ಖಾಸಗಿ ಆರೋಗ್ಯ ದಾಖಲೆ ಸಿಗುತ್ತದೆ.",
    "help.answer.doctor": "ವೈದ್ಯರು ತಮ್ಮ ಆಸ್ಪತ್ರೆ ನೀಡಿದ ವೈದ್ಯ ID ಮತ್ತು ಪಾಸ್‌ವರ್ಡ್‌ನಿಂದ ಸೈನ್ ಇನ್ ಮಾಡುತ್ತಾರೆ — ಮೊಬೈಲ್ OTP ಇಲ್ಲ. ಮೊದಲ ಬಾರಿ ವೈದ್ಯರು ವೈದ್ಯ ಡ್ಯಾಶ್‌ಬೋರ್ಡ್ ಪ್ರವೇಶಿಸುವ ಮೊದಲು ಸಣ್ಣ ನೋಂದಣಿ (ಗುರುತು, ಆಸ್ಪತ್ರೆ ಗುರುತುಚೀಟಿಗಳು, ವೃತ್ತಿಪರ ವಿವರಗಳು, ಸಮ್ಮತಿ) ಪೂರ್ಣಗೊಳಿಸುತ್ತಾರೆ. ಅಲ್ಲಿ ಅವರು ರೋಗಿ ಪ್ರಕರಣಗಳು, ಆದ್ಯತೆ ಸರತಿ ಮತ್ತು ಕ್ಲಿನಿಕಲ್ ಟಿಪ್ಪಣಿಗಳನ್ನು ಪರಿಶೀಲಿಸಬಹುದು.",
    "help.answer.intake": "ಮೆಡಿಕಿಯೋಸ್ಕ್ ಆಸ್ಪತ್ರೆಯಲ್ಲಿ ಸ್ವಯಂ-ಸೇವಾ ಟರ್ಮಿನಲ್. ರೋಗಿ ತಮ್ಮನ್ನು ಗುರುತಿಸುತ್ತಾರೆ, ಸಮ್ಮತಿ ನೀಡುತ್ತಾರೆ, ನಂತರ ಮಾರ್ಗದರ್ಶಿತ ಕ್ಲಿನಿಕಲ್-ಇತಿಹಾಸ ಪ್ರಶ್ನಾವಳಿಯನ್ನು ಭರ್ತಿ ಮಾಡುತ್ತಾರೆ (ಧ್ವನಿ/ಪಠ್ಯ/ಟೈಪಿಂಗ್). ಪತ್ರಗಳನ್ನು ಸ್ಕ್ಯಾನ್/OCR ಮಾಡಲಾಗುತ್ತದೆ. AI ರೆಡ್-ಫ್ಲ್ಯಾಗ್ ಎಚ್ಚರಿಕೆಗಳೊಂದಿಗೆ ಮೂಲ-ಬೆಂಬಲಿತ ಕ್ಲಿನಿಕಲ್ ಸಾರಾಂಶವನ್ನು ರಚಿಸುತ್ತದೆ, ಅದನ್ನು ವೈದ್ಯರು ನಂತರ ಪರಿಶೀಲಿಸುತ್ತಾರೆ.",
    "help.answer.timeline": "ಆರೋಗ್ಯ ಸಮಯರೇಖೆ ರೋಗಿಯ ಭೇಟಿಗಳು, ಪತ್ರಗಳು, ಔಷಧಿಗಳು, ಲ್ಯಾಬ್ ವರದಿಗಳು ಮತ್ತು ಲಸಿಕೆಗಳನ್ನು ಒಂದೇ ಸ್ಕ್ರಾಲ್‌ನಲ್ಲಿ, ವರ್ಷದ ಪ್ರಕಾರ ಗುಂಪು ಮಾಡಿ ತೋರಿಸುತ್ತದೆ. ಭೇಟಿ, ಪತ್ರ, ಔಷಧಿ, ವರದಿ ಅಥವಾ ಲಸಿಕೆ ಪ್ರಕಾರ ಫಿಲ್ಟರ್ಗಳು ಸಂಕುಚಿತಗೊಳಿಸಲು ಅನುವು ಮಾಡಿಕೊಡುತ್ತವೆ.",
    "help.answer.documents": "ರೋಗಿಗಳು ಪ್ರಿಸ್ಕ್ರಿಪ್ಷನ್ ಚಿತ್ರಗಳು, ಲ್ಯಾಬ್ ವರದಿಗಳು ಮತ್ತು ಡಿಸ್ಚಾರ್ಜ್ ಸಾರಾಂಶಗಳನ್ನು ಅಪ್‌ಲೋಡ್ ಅಥವಾ ಸ್ಕ್ಯಾನ್ ಮಾಡಬಹುದು. OCR ಪಠ್ಯವನ್ನು ಓದುತ್ತದೆ ಮತ್ತು ಕೇರ್ ಲಿಂಕ್ ಔಷಧಿ ಹೆಸರು, ಡೋಸ್, ದಿನಾಂಕ ಮತ್ತು ಆಸ್ಪತ್ರೆಯಂತಹ ಕ್ಷೇತ್ರಗಳನ್ನು ಹೊರತೆಗೆದು ಆರೋಗ್ಯ ದಾಖಲೆಗೆ ಸೇರಿಸುತ್ತದೆ.",
    "help.answer.language": "ಕೇರ್ ಲಿಂಕ್ ಇಂಗ್ಲಿಷ್, ಹಿಂದಿ ಮತ್ತು ಉರ್ದು ಸೇರಿದಂತೆ ಅನೇಕ ಭಾಷೆಗಳನ್ನು ಬೆಂಬಲಿಸುತ್ತದೆ. ಉರ್ದು ಲೇಔಟ್ ಅನ್ನು ಬಲ-ನಿಂದ-ಎಡಕ್ಕೆ (RTL) ಸಹ ತಿರುಗಿಸುತ್ತದೆ. ಸ್ವಾಗತ ಪುಟದ ಭಾಷಾ ಪರದೆಯಿಂದ ನೀವು ಭಾಷೆಯನ್ನು ಯಾವಾಗ ಬೇಕಾದರೂ ಬದಲಾಯಿಸಬಹುದು.",
    "help.answer.theme": "ಪ್ರವೇಶಿಸುವಿಕೆ ಪರದೆ ನಿಮಗೆ ಥೀಮ್ ಬಣ್ಣವನ್ನು ಆಯ್ಕೆಮಾಡಲು ನೀಡುತ್ತದೆ — ಬಿಳಿ, ನೀಲಿ, ಹಸಿರು, ಗುಲಾಬಿ, ಚಿನ್ನದ ಹಳದಿ ಅಥವಾ ಕಪ್ಪು. ಇಡೀ ಅಪ್ ತಕ್ಷಣ ಅಪ್‌ಡೇಟ್ ಆಗುತ್ತದೆ. ಸ್ವಾಗತ ಪುಟದ ಪ್ರವೇಶಿಸುವಿಕೆ ಗುಂಡಿಯಿಂದ ನೀವು ಅದನ್ನು ತಲುಪಬಹುದು.",
    "help.answer.ai": "ನಾನು ಕೇರ್ ಲಿಂಕ್ ಸಹಾಯಕ. ಕೇರ್ ಲಿಂಕ್ ಆಸ್ಪತ್ರೆಗಳು ಮತ್ತು ಕ್ಲಿನಿಕ್‌ಗಳಿಗಾಗಿ AI-ಸಹಾಯಕ, ಮೂಲ-ಬೆಂಬಲಿತ ಕ್ಲಿನಿಕಲ್ ಇತಿಹಾಸ ಮತ್ತು ರೋಗಿ-ಸ್ವೀಕಾರ ಅಪ್. ಅದರ ಪ್ರಮುಖ ಭಾಗಗಳು: ರೋಗಿ ನೋಂದಣಿ ಮತ್ತು ಪ್ರೊಫೈಲ್, ಆಸ್ಪತ್ರೆ-ನೀಡಿದ ಗುರುತುಚೀಟಿಗಳಿಂದ ವೈದ್ಯ ಲಾಗಿನ್, ಮೆಡಿಕಿಯೋಸ್ಕ್ ಸ್ವಯಂ-ಸೇವಾ ರೋಗಿ-ಸ್ವೀಕಾರ ಟರ್ಮಿನಲ್, ರೆಡ್-ಫ್ಲ್ಯಾಗ್ ಪತ್ತೆಯೊಂದಿಗೆ AI-ರಚಿಸಿದ ಕ್ಲಿನಿಕಲ್ ಸಾರಾಂಶಗಳು, ಪತ್ರ OCR, ಆರೋಗ್ಯ ಸಮಯರೇಖೆ, ಭಾಷೆ/ಪ್ರವೇಶಿಸುವಿಕೆ ಥೀಮ್‌ಗಳು ಮತ್ತು ABDM/ಸಮ್ಮತಿ-ಸಿದ್ಧ ವಿನ್ಯಾಸ. ಇವುಗಳಲ್ಲಿ ಯಾವುದರ ಬಗ್ಗೆಯೂ ಕೇಳಿ.",
    "help.suggest.1": "ಈ ಅಪ್ ಏನು ಮಾಡುತ್ತದೆ?",
    "help.suggest.2": "ರೋಗಿಗಳು ಹೇಗೆ ನೋಂದಾಯಿಸುತ್ತಾರೆ?",
    "help.suggest.3": "ವೈದ್ಯರು ಹೇಗೆ ಲಾಗಿನ್ ಆಗುತ್ತಾರೆ?",
    "help.suggest.4": "ಮೆಡಿಕಿಯೋಸ್ಕ್ ಎಂದರೇನು?",
    "help.suggest.5": "ಪತ್ರ ಸ್ಕ್ಯಾನಿಂಗ್ ಹೇಗೆ ಕೆಲಸ ಮಾಡುತ್ತದೆ?",

