    "clinical.scanQrCta": "QR സ്കാൻ ചെയ്യുക",
    "clinical.consentHeader": "സമ്മതവും സ്വകാര്യതയും",
    "clinical.consentProtected": "നിങ്ങളുടെ ഡാറ്റ പരിരക്ഷിതമാണ്",
    "clinical.consentBodyLong": "ഡിജിറ്റൽ പേഴ്സണൽ ഡാറ്റ പ്രൊട്ടക്ഷൻ ആക്ട് 2023-നും ABDM സമ്മത ചട്ടക്കൂടിനും അനുസൃതം. നിങ്ങൾ നിയന്ത്രണത്തിലാണ് — സമ്മതം എപ്പോൾ വേണമെങ്കിലും പിൻവലിക്കാം, സമർപ്പണത്തിന് ശേഷം താൽക്കാലിക സെഷൻ ഡാറ്റ മായ്ക്കും.",
    "clinical.consentReview": "ഞങ്ങളെ എന്ത് ചെയ്യാൻ അനുവദിക്കുന്നുവെന്ന് കാണുക",
    "clinical.consentRevoke": "ഏത് അനുമതിയും പിന്നീട് ക്രമീകരണങ്ങളിൽ പിൻവലിക്കാം",
