    "clinical.pushHis": "ആശുപത്രി സിസ്റ്റത്തിലേക്ക് സംഗ്രഹം അയയ്ക്കുന്നു",
    "clinical.linkAbha": "ABHA ആരോഗ്യ രേഖയിലേക്ക് ലിങ്ക് ചെയ്യുന്നു",
    "clinical.clearData": "താൽക്കാലിക സെഷൻ ഡാറ്റ മായ്ക്കുന്നു",
    "clinical.allSet": "നിങ്ങൾ തയ്യാറാണ്!",
    "clinical.allSetBody": "നിങ്ങളുടെ ക്ലിനിക്കൽ ചരിത്രവും പ്രമാണങ്ങളും നിങ്ങളുടെ ഡോക്ടർക്ക് അയച്ചു. ദയവായി കൺസൾട്ടേഷൻ മുറിയിലേക്ക് പോകുക.",
