    "clinical.sessionCleared": "സെഷൻ ഡാറ്റ മായ്ച്ചു · സമ്മതം സംരക്ഷിച്ചു",
    "clinical.documentsDigitized": "പ്രമാണം(ങ്ങൾ) ഡിജിറ്റൈസ് ചെയ്തു",
    "clinical.priorityFlag": "മുൻഗണന അവലോകനത്തിനായി ഫ്ളാഗ് ചെയ്തു",
    "clinical.priorityBody": "നിങ്ങളുടെ കേസ് അടിയന്തര ശ്രദ്ധയ്ക്കായി ഫ്ളാഗ് ചെയ്തു. കൗണ്ടറിൽ ഇത് പറയുക.",
