    "clinical.pushHis": "ਹਸਪਤਾਲ ਪ੍ਰਣਾਲੀ ਨੂੰ ਸੰਖੇਪ ਭੇਜਿਆ ਜਾ ਰਿਹਾ ਹੈ",
    "clinical.linkAbha": "ABHA ਸਿਹਤ ਰਿਕਾਰਡ ਨਾਲ ਜੁੜ ਰਿਹਾ ਹੈ",
    "clinical.clearData": "ਅਸਥਾਈ ਸੈਸ਼ਨ ਡੇਟਾ ਸਾਫ਼ ਹੋ ਰਿਹਾ ਹੈ",
    "clinical.allSet": "ਤੁਸੀਂ ਤਿਆਰ ਹੋ!",
