    "help.title": "ਮਦਦ ਸਹਾਇਕ",
    "help.subtitle": "ਕੇਅਰ ਲਿੰਕ ਦੇ ਹਰ ਹਿੱਸੇ ਦੀ ਵਿਆਖਿਆ",
    "help.inputPlaceholder": "ਕੇਅਰ ਲਿੰਕ ਕਿਵੇਂ ਕੰਮ ਕਰਦਾ ਹੈ ਪੁੱਛੋ…",
    "help.backAria": "ਵਾਪਸ",
    "help.welcome": "ਸਤ ਸ੍ਰੀ ਅਕਾਲ! ਮੈਂ ਕੇਅਰ ਲਿੰਕ ਦਾ ਮਾਰਗਦਰਸ਼ਕ ਹਾਂ। ਇਹ ਐਪ ਕਿਵੇਂ ਕੰਮ ਕਰਦੀ ਹੈ ਸਮਝਾ ਸਕਦਾ ਹਾਂ — ਮਰੀਜ਼ ਰਜਿਸਟ੍ਰੇਸ਼ਨ, ਡਾਕਟਰ ਲੌਗਇਨ, ਮੇਡੀਕਿਓਸਕ, ਦਸਤਾਵੇਜ਼ ਸਕੈਨਿੰਗ, AI ਸੰਖੇਪ, ਭਾਸ਼ਾਵਾਂ ਅਤੇ ਥੀਮ। \"ਇਹ ਐਪ ਕੀ ਕਰਦੀ ਹੈ?\" ਕੁਝ ਵੀ ਪੁੱਛੋ।",
    "help.answer.register": "ਕੇਅਰ ਲਿੰਕ ਮਰੀਜ਼ ਕੇਸ-ਲੈਣ ਵਾਲੀ ਐਪ ਹੈ। ਸ਼ੁਰੂ ਕਰਨ ਲਈ ਮਰੀਜ਼ ਆਪਣਾ ਮੋਬਾਈਲ ਨੰਬਰ ਦਾਖਲ ਕਰਦਾ ਹੈ, OTP ਨਾਲ ਤਸਦੀਕ ਕਰਦਾ ਹੈ, ਫਿਰ ਪੂਰਾ ਨਾਮ, ਅਧਾਰ ਸਿਹਤ ਵੇਰਵੇ ਅਤੇ ਸਹਿਮਤੀ ਰਿਕਾਰਡ ਕਰਦਾ ਹੈ। ਰਜਿਸਟ੍ਰੇਸ਼ਨ ਤੋਂ ਬਾਅਦ ਉਨ੍ਹਾਂ ਨੂੰ ਪ੍ਰੋਫਾਈਲ, ਟਾਈਮਲਾਈਨ, ਦਸਤਾਵੇਜ਼ ਆਦਿ ਨਾਲ ਨਿੱਜੀ ਸਿਹਤ ਰਿਕਾਰਡ ਮਿਲਦਾ ਹੈ।",
    "help.answer.doctor": "ਡਾਕਟਰ ਆਪਣੇ ਹਸਪਤਾਲ ਵੱਲੋਂ ਦਿੱਤੇ ਡਾਕਟਰ ID ਅਤੇ ਪਾਸਵਰਡ ਨਾਲ ਸਾਈਨ ਇਨ ਕਰਦੇ ਹਨ — ਮੋਬਾਈਲ OTP ਨਹੀਂ। ਪਹਿਲੀ ਵਾਰ ਡਾਕਟਰ ਡੈਸ਼ਬੋਰਡ ਵਿੱਚ ਜਾਣ ਤੋਂ ਪਹਿਲਾਂ ਛੋਟੀ ਰਜਿਸਟ੍ਰੇਸ਼ਨ (ਪਛਾਣ, ਹਸਪਤਾਲ ਪ੍ਰਮਾਣ ਪੱਤਰ, ਪੇਸ਼ੇਵਰ ਵੇਰਵੇ, ਸਹਿਮਤੀ) ਮੁਕੰਮਲ ਕਰਦੇ ਹਨ। ਉੱਥੇ ਉਹ ਮਰੀਜ਼ ਕੇਸ, ਤਰਜੀਹ ਕਤਾਰ ਅਤੇ ਕਲੀਨਿਕਲ ਨੋਟ ਸਮੀਖਿਆ ਕਰ ਸਕਦੇ ਹਨ।",
    "help.answer.intake": "ਮੇਡੀਕਿਓਸਕ ਹਸਪਤਾਲ ਵਿੱਚ ਸਵੈ-ਸੇਵਾ ਟਰਮੀਨਲ ਹੈ। ਮਰੀਜ਼ ਆਪਣੀ ਪਛਾਣ ਕਰਦਾ ਹੈ, ਸਹਿਮਤੀ ਦਿੰਦਾ ਹੈ, ਫਿਰ ਮਾਰਗਦਰਸ਼ਿਤ ਕਲੀਨਿਕਲ-ਇਤਿਹਾਸ ਪ੍ਰਸ਼ਨਾਵਲੀ (ਆਵਾਜ਼/ਟੈਕਸਟ/ਟਾਈਪਿੰਗ) ਭਰਦਾ ਹੈ। ਦਸਤਾਵੇਜ਼ ਸਕੈਨ/OCR ਹੁੰਦੇ ਹਨ। AI ਰੈੱਡ-ਫਲੈਗ ਸੁਚੇਤਨਾਵਾਂ ਨਾਲ ਸਰੋਤ-ਸਮਰਥਿਤ ਕਲੀਨਿਕਲ ਸੰਖੇਪ ਬਣਾਉਂਦਾ ਹੈ, ਜਿਸਨੂੰ ਡਾਕਟਰ ਬਾਅਦ ਵਿੱਚ ਤਸਦੀਕ ਕਰਦੇ ਹਨ।",
    "help.answer.timeline": "ਸਿਹਤ ਟਾਈਮਲਾਈਨ ਮਰੀਜ਼ ਦੀਆਂ ਮੁਲਾਕਾਤਾਂ, ਦਸਤਾਵੇਜ਼, ਦਵਾਈਆਂ, ਲੈਬ ਰਿਪੋਰਟਾਂ ਅਤੇ ਟੀਕਾਕਰਨ ਇੱਕ ਸਕ੍ਰੋਲ ਵਿੱਚ, ਸਾਲ ਅਨੁਸਾਰ ਸਮੂਹ ਬਣਾ ਦਿਖਾਉਂਦੀ ਹੈ। ਮੁਲਾਕਾਤ, ਦਸਤਾਵੇਜ਼, ਦਵਾਈ, ਰਿਪੋਰਟ ਜਾਂ ਟੀਕੇ ਅਨੁਸਾਰ ਫਿਲਟਰ ਛੋਟਾ ਕਰਨ ਦਿੰਦੇ ਹਨ।",
    "help.answer.documents": "ਮਰੀਜ਼ ਨੁਸਖੇ ਦੀਆਂ ਤਸਵੀਰਾਂ, ਲੈਬ ਰਿਪੋਰਟਾਂ ਅਤੇ ਡਿਸਚਾਰਜ ਸੰਖੇਪ ਅੱਪਲੋਡ ਜਾਂ ਸਕੈਨ ਕਰ ਸਕਦੇ ਹਨ। OCR ਟੈਕਸਟ ਪੜ੍ਹਦਾ ਹੈ ਅਤੇ ਕੇਅਰ ਲਿੰਕ ਦਵਾਈ ਦਾ ਨਾਮ, ਮਾਤਰਾ, ਮਿਤੀ ਅਤੇ ਹਸਪਤਾਲ ਵਰਗੇ ਫੀਲਡ ਕੱਢ ਕੇ ਸਿਹਤ ਰਿਕਾਰਡ ਵਿੱਚ ਸ਼ਾਮਲ ਕਰਦਾ ਹੈ।",
    "help.answer.language": "ਕੇਅਰ ਲਿੰਕ ਅੰਗਰੇਜ਼ੀ, ਹਿੰਦੀ ਅਤੇ ਉਰਦੂ ਸਮੇਤ ਕਈ ਭਾਸ਼ਾਵਾਂ ਦਾ ਸਮਰਥਨ ਕਰਦਾ ਹੈ। ਉਰਦੂ ਲੇਆਉਟ ਸੱਜੇ-ਤੋਂ-ਖੱਬੇ (RTL) ਵੀ ਹੁੰਦਾ ਹੈ। ਸਵਾਗਤੀ ਪੰਨੇ ਦੀ ਭਾਸ਼ਾ ਸਕ੍ਰੀਨ ਤੋਂ ਕਿਸੇ ਵੀ ਸਮੇਂ ਭਾਸ਼ਾ ਬਦਲ ਸਕਦੇ ਹੋ।",
    "help.answer.theme": "ਪਹੁੰਚਯੋਗਤਾ ਸਕ੍ਰੀਨ ਤੁਹਾਨੂੰ ਥੀਮ ਰੰਗ ਚੁਣਨ ਦਿੰਦੀ ਹੈ — ਚਿੱਟਾ, ਨੀਲਾ, ਹਰਾ, ਗੁਲਾਬੀ, ਸੁਨਹਿਰੀ ਪੀਲਾ ਜਾਂ ਕਾਲਾ। ਪੂਰਾ ਐਪ ਤੁਰੰਤ ਅੱਪਡੇਟ ਹੁੰਦਾ ਹੈ। ਸਵਾਗਤੀ ਪੰਨੇ ਦੇ ਪਹੁੰਚਯੋਗਤਾ ਬਟਨ ਤੋਂ ਇਹ ਲੱਭ ਸਕਦੇ ਹੋ।",
    "help.answer.ai": "ਮੈਂ ਕੇਅਰ ਲਿੰਕ ਸਹਾਇਕ ਹਾਂ। ਕੇਅਰ ਲਿੰਕ ਹਸਪਤਾਲਾਂ ਅਤੇ ਕਲੀਨਿਕਾਂ ਲਈ AI-ਸਹਾਇਤਾ, ਸਰੋਤ-ਸਮਰਥਿਤ ਕਲੀਨਿਕਲ ਇਤਿਹਾਸ ਅਤੇ ਕੇਸ-ਲੈਣ ਵਾਲੀ ਐਪ ਹੈ। ਮੁੱਖ ਹਿੱਸੇ: ਮਰੀਜ਼ ਰਜਿਸਟ੍ਰੇਸ਼ਨ ਅਤੇ ਪ੍ਰੋਫਾਈਲ, ਹਸਪਤਾਲ-ਦਿੱਤੇ ਪ੍ਰਮਾਣ ਪੱਤਰਾਂ ਨਾਲ ਡਾਕਟਰ ਲੌਗਇਨ, ਮੇਡੀਕਿਓਸਕ ਸਵੈ-ਸੇਵਾ ਕੇਸ-ਲੈਣ ਟਰਮੀਨਲ, ਰੈੱਡ-ਫਲੈਗ ਖੋਜ ਨਾਲ AI-ਬਣਾਏ ਕਲੀਨਿਕਲ ਸੰਖੇਪ, ਦਸਤਾਵੇਜ਼ OCR, ਸਿਹਤ ਟਾਈਮਲਾਈਨ, ਭਾਸ਼ਾ/ਪਹੁੰਚਯੋਗਤਾ ਥੀਮ ਅਤੇ ABDM/ਸਹਿਮਤੀ-ਤਿਆਰ ਡਿਜ਼ਾਈਨ। ਇਨ੍ਹਾਂ ਵਿੱਚੋਂ ਕਿਸੇ ਬਾਰੇ ਪੁੱਛੋ।",
    "help.suggest.1": "ਇਹ ਐਪ ਕੀ ਕਰਦੀ ਹੈ?",
    "help.suggest.2": "ਮਰੀਜ਼ ਕਿਵੇਂ ਰਜਿਸਟਰ ਕਰਦੇ ਹਨ?",
    "help.suggest.3": "ਡਾਕਟਰ ਕਿਵੇਂ ਲੌਗਇਨ ਕਰਦੇ ਹਨ?",
    "help.suggest.4": "ਮੇਡੀਕਿਓਸਕ ਕੀ ਹੈ?",
    "help.suggest.5": "ਦਸਤਾਵੇਜ਼ ਸਕੈਨਿੰਗ ਕਿਵੇਂ ਕੰਮ ਕਰਦੀ ਹੈ?",

