    "clinical.consentBodyLong": "ଡିଜିଟାଲ୍ ପର୍ସନାଲ୍ ଡାଟା ପ୍ରୋଟେକ୍ସନ୍ ଆକ୍ଟ 2023 ଓ ABDM ସହମତି ଢାଞ୍ଚା ଅନୁସାରେ। ଆପଣ ନିୟନ୍ତ୍ରଣରେ ଅଛନ୍ତି — ସହମତି ଯେକୌଣସି ସମୟରେ ଫେରାଯାଇପାରେ ଓ ଦାଖଲ ପରେ ଅସ୍ଥାୟୀ ଅଧିବେଶନ ଡାଟା ସଫା ହୁଏ।",
