    "help.title": "ସାହାଯ୍ୟ ସହାୟକ",
    "help.subtitle": "କେୟାର ଲିଙ୍କର ପ୍ରତ୍ୟେକ ଅଂଶ ବୁଝାଇବା",
    "help.inputPlaceholder": "କେୟାର ଲିଙ୍କ କିପରି କାମ କରେ ପଚାରନ୍ତୁ…",
    "help.backAria": "ପଛକୁ",
    "help.welcome": "ନମସ୍କାର! ମୁଁ କେୟାର ଲିଙ୍କର ମାର୍ଗଦର୍ଶକ। ଏହି ଆପ୍ କିପରି କାମ କରେ ବୁଝାଇପାରିବି — ରୋଗୀ ପଞ୍ଜୀକରଣ, ଡାକ୍ତର ଲଗଇନ୍, ମେଡିକିଓସ୍କ, ଦସ୍ତାବିଜ ସ୍କାନିଂ, AI ସଂକ୍ଷିପ୍ତ, ଭାଷା ଓ ଥିମ୍। \"ଏହି ଆପ୍ କ'ଣ କରେ?\" ଯେ କିଛି ପଚାରନ୍ତୁ।",
    "help.answer.register": "କେୟାର ଲିଙ୍କ ଏକ ରୋଗୀ-କେସ ନେବା ଆପ୍। ଆରମ୍ଭ କରିବାକୁ ରୋଗୀ ତାଙ୍କ ମୋବାଇଲ୍ ନମ୍ବର ଲେଖନ୍ତି, OTP ଦ୍ୱାରା ଯାଞ୍ଚ କରନ୍ତି, ତାପରେ ପୂର୍ଣ୍ଣ ନାମ, ମୂଳ ସ୍ୱାସ୍ଥ୍ୟ ତଥ୍ୟ ଓ ସହମତି ରେକର୍ଡ କରନ୍ତି। ପଞ୍ଜୀକରଣ ପରେ ସେମାନଙ୍କୁ ପ୍ରୋଫାଇଲ୍, ଟାଇମଲାଇନ୍, ଦସ୍ତାବିଜ ଇତ୍ୟାଦି ସହ ଏକ ବ୍ୟକ୍ତିଗତ ସ୍ୱାସ୍ଥ୍ୟ ରେକର୍ଡ ମିଳେ।",
    "help.answer.doctor": "ଡାକ୍ତରମାନେ ତାଙ୍କ ହସ୍ପିଟାଲ ଦେଇଥିବା ଡାକ୍ତର ID ଓ ପାସୱାର୍ଡ ଦ୍ୱାରା ସାଇନ୍-ଇନ୍ କରନ୍ତି — ମୋବାଇଲ୍ OTP ନୁହେଁ। ପ୍ରଥମେ ଡାକ୍ତର ଡ୍ୟାସବୋର୍ଡକୁ ଯିବା ପୂର୍ବରୁ ଏକ ସଂକ୍ଷିପ୍ତ ପଞ୍ଜୀକରଣ (ପରିଚୟ, ହସ୍ପିଟାଲ ପ୍ରମାଣପତ୍ର, ବୃତ୍ତିଗତ ତଥ୍ୟ, ସହମତି) ସମ୍ପୂର୍ଣ୍ଣ କରନ୍ତି। ସେଠାରେ ସେମାନେ ରୋଗୀ ମାମଲା, ଅଗ୍ରାଧିକାର ଧାଡ଼ି ଓ କ୍ଲିନିକାଲ ନୋଟ୍ ସମୀକ୍ଷା କରିପାରନ୍ତି।",
    "help.answer.intake": "ମେଡିକିଓସ୍କ ହସ୍ପିଟାଲରେ ଏକ ସ୍ୱୟଂ-ସେବା ଟର୍ମିନାଲ। ରୋଗୀ ପରିଚୟ କରନ୍ତି, ସହମତି ଦିଅନ୍ତି, ତାପରେ ମାର୍ଗଦର୍ଶିତ କ୍ଲିନିକାଲ-ଇତିହାସ ପ୍ରଶ୍ନାବଳୀ (ସ୍ୱର/ଟେକ୍ସଟ/ଟାପ୍) ସମ୍ପୂର୍ଣ୍ଣ କରନ୍ତି। ଦସ୍ତାବିଜ ସ୍କାନ/OCR ହୁଏ। AI ରେଡ୍ ଫ୍ଲାଗ୍ ସତର୍କତା ସହ ସନ୍ଦର୍ଭ-ପ୍ରମାଣିତ କ୍ଲିନିକାଲ ସଂକ୍ଷିପ୍ତ ତିଆରି କରେ, ଯାହାକୁ ଡାକ୍ତର ପରେ ଯାଞ୍ଚ କରନ୍ତି।",
    "help.answer.timeline": "ସ୍ୱାସ୍ଥ୍ୟ ଟାଇମଲାଇନ୍ ରୋଗୀଙ୍କ ଭେଟ, ଦସ୍ତାବିଜ, ଔଷଧ, ଲ୍ୟାବ ରିପୋର୍ଟ ଓ ଟିକା ଏକ ସ୍କ୍ରୋଲରେ, ବର୍ଷ ଅନୁସାରେ ସମୂହ କରି ଦେଖାଏ। ଭେଟ, ଦସ୍ତାବିଜ, ଔଷଧ, ରିପୋର୍ଟ କିମ୍ବା ଟିକା ଅନୁସାରେ ଫିଲ୍ଟର ସଂକୀର୍ଣ୍ଣ କରେ।",
    "help.answer.documents": "ରୋଗୀ ପ୍ରେସକ୍ରିପସନ୍ ଫଟୋ, ଲ୍ୟାବ ରିପୋର୍ଟ ଓ ଡିସଚାର୍ଜ ସଂକ୍ଷିପ୍ତ ଅପଲୋଡ୍ କିମ୍ବା ସ୍କାନ କରିପାରିବେ। OCR ଟେକ୍ସଟ ପଢ଼େ ଏବଂ କେୟାର ଲିଙ୍କ ଔଷଧ ନାମ, ମାତ୍ରା, ତାରିଖ ଓ ହସ୍ପିଟାଲ ଭଳି କ୍ଷେତ୍ର ବାହାର କରି ସ୍ୱାସ୍ଥ୍ୟ ରେକର୍ଡରେ ଯୋଡ଼େ।",
    "help.answer.language": "କେୟାର ଲିଙ୍କ ଇଂରାଜୀ, ହିନ୍ଦୀ ଓ ଉର୍ଦ୍ଦୁ ସମେତ ଅନେକ ଭାଷାର ସମର୍ଥନ କରେ। ଉର୍ଦ୍ଦୁ ଲେଆଉଟ ମଧ୍ୟ ଡାହାଣ-ରୁ-ବାମ (RTL) ଅଟେ। ସ୍ୱାଗତ ପୃଷ୍ଠା ଭାଷା ସ୍କ୍ରିନରୁ ଯେକୌଣସି ସମୟରେ ଭାଷା ବଦଳାଇପାରିବେ।",
    "help.answer.theme": "ସୁଲଭତା ସ୍କ୍ରିନ ଆପଣଙ୍କୁ ଥିମ୍ ରଙ୍ଗ ବାଛିବାକୁ ଦିଏ — ଧଳା, ନୀଳ, ସବୁଜ, ଗୋଲାପୀ, ସୁନାଳୀ କିମ୍ବା କଳା। ସମ୍ପୂର୍ଣ୍ଣ ଆପ୍ ତୁରନ୍ତ ଅପଡେଟ ହୁଏ। ସ୍ୱାଗତ ପୃଷ୍ଠାର ସୁଲଭତା ବଟନରୁ ଏହା ମିଳିବ।",
    "help.answer.ai": "ମୁଁ କେୟାର ଲିଙ୍କ ସହାୟକ। କେୟାର ଲିଙ୍କ ହସ୍ପିଟାଲ ଓ କ୍ଲିନିକ ପାଇଁ ଏକ AI-ସହାୟିତ, ସନ୍ଦର୍ଭ-ପ୍ରମାଣିତ କ୍ଲିନିକାଲ ଇତିହାସ ଓ କେସ ନେବା ଆପ୍। ମୁଖ୍ୟ ଅଂଶ: ରୋଗୀ ପଞ୍ଜୀକରଣ ଓ ପ୍ରୋଫାଇଲ, ହସ୍ପିଟାଲ-ଦେୟା ପ୍ରମାଣପତ୍ର ସହ ଡାକ୍ତର ଲଗଇନ୍, ମେଡିକିଓସ୍କ ସ୍ୱୟଂ-ସେବା କେସ ନେବା ଟର୍ମିନାଲ, ରେଡ୍ ଫ୍ଲାଗ୍ ଚିହ୍ନଟ ସହ AI-ଉତ୍ପନ୍ନ କ୍ଲିନିକାଲ ସଂକ୍ଷିପ୍ତ, ଦସ୍ତାବିଜ OCR, ସ୍ୱାସ୍ଥ୍ୟ ଟାଇମଲାଇନ୍, ଭାଷା/ସୁଲଭତା ଥିମ୍ ଓ ABDM/ସହମତି-ପ୍ରସ୍ତୁତ ଡିଜାଇନ୍। ଏସବୁର ଯେ କୌଣସି ବିଷୟରେ ପଚାରନ୍ତୁ।",
    "help.suggest.1": "ଏହି ଆପ୍ କ'ଣ କରେ?",
    "help.suggest.2": "ରୋଗୀ କିପରି ପଞ୍ଜୀକରଣ କରନ୍ତି?",
    "help.suggest.3": "ଡାକ୍ତର କିପରି ଲଗଇନ୍ କରନ୍ତି?",
    "help.suggest.4": "ମେଡିକିଓସ୍କ କ'ଣ?",
    "help.suggest.5": "ଦସ୍ତାବିଜ ସ୍କାନିଂ କିପରି କାମ କରେ?",

