      "ନମସ୍କାର! ମୁଁ କେୟାର ଲିଙ୍କ AI, ଆପଣଙ୍କ ଅନବୋର୍ଡିଂ ସହାୟକ। ରୋଗୀ ପଞ୍ଜୀକରଣ ଆରମ୍ଭ କରିବାକୁ, ଡାକ୍ତର ଭାବେ ଯୋଗ ଦେବାକୁ, ଭାଷା ବଦଳାଇବାକୁ କିମ୍ବା ହେଲ୍ପ ଡେସ୍କ ଖୋଲିବାକୁ ମୋତେ ପଚାରନ୍ତୁ।",
