    "help.title": "সহায় সহায়ক",
    "help.subtitle": "কেୟাৰ লিংকৰ প্ৰতিটো অংশ বাখ্যা",
    "help.inputPlaceholder": "কেୟাৰ লিংক কেনেদৰে কাম কৰে সুধক…",
    "help.backAria": "পিছলৈ",
    "help.welcome": "নমস্কাৰ! মই কেୟাৰ লিংকৰ পথ-প্ৰদৰ্শক। এই এপটো কেনেদৰে কাম কৰে বাখ্যা কৰিব পাৰোঁ — ৰোগী পঞ্জীয়ন, ডাক্তৰ লগইন, মেডিকিঅস্ক, দস্তাবেজ স্কেনিং, AI সাৰাংশ, ভাষা আৰু থিম। \"এই এপটোৱে কি কৰে?\" যি কোনো সুধক।",
    "help.answer.register": "কেୟাৰ লিংক এটা ৰোগী-কেছ লোয়া এপ। আৰম্ভ কৰিবলৈ ৰোগীয়ে তেওঁলোকৰ মোবাইল নম্বৰ লিখে, OTP ৰে নিশ্চিত কৰে, তাৰপিছত সম্পূৰ্ণ নাম, ভিত্তি স্বাস্থ্য তথ্য আৰু সন্মতি ৰেকৰ্ড কৰে। পঞ্জীয়ন পিছত তেওঁলোকে প্ৰফাইল, টাইমলাইন, দস্তাবেজ ইত্যাদি সৈতে এটা ব্যক্তিগত স্বাস্থ্য ৰেকৰ্ড পায়।",
    "help.answer.doctor": "ডাক্তৰে তেওঁলোকৰ হস্পিতালে দিয়া ডাক্তৰ ID আৰু পাছৱৰ্ডেৰে সাইন-ইন কৰে — মোবাইল OTP নহয়। প্ৰথমে ডাক্তৰ ডেশ্ববোৰ্ডলৈ যোৱাৰ আগত এটা সংক্ষিপ্ত পঞ্জীয়ন (পৰিচয়, হস্পিতাল প্ৰমাণপত্ৰ, বৃত্তিগত তথ্য, সন্মতি) সম্পূৰ্ণ কৰে। তাতে তেওঁলোকে ৰোগী মামলা, অগ্ৰাধিকাৰ কাতাৰ আৰু ক্লিনিকেল নোট পৰ্যালোচনা কৰিব পাৰে।",
    "help.answer.intake": "মেডিকিঅস্ক হস্পিতালৰ এটা স্বয়ং-সেৱা টার্মিনাল। ৰোগীয়ে পৰিচয় কৰে, সন্মতি দিয়ে, তাৰপিছত পথ-নির্দেশিত ক্লিনিকেল-ইতিহাস প্রশ্নাৱলী (স্বৰ/টেক্সট/টিপ) সম্পূৰ্ণ কৰে। দস্তাবেজ স্কেন/OCR হয়। AI ৰেড ফ্ল্যাগ সতর্কতা সৈতে সন্দৰ্ভ-প্রমাণিত ক্লিনিকেল সাৰাংশ গঠন কৰে, যাক ডাক্তৰে পিছত নিশ্চিত কৰে।",
    "help.answer.timeline": "স্বাস্থ্য টাইমলাইন ৰোগীৰ বিবাহ, দস্তাবেজ, ঔষধ, ল্যাব ৰিপোৰ্ট আৰু পিকনি এক স্ক্রোলত, বছৰ অনুযায়ী সৈঙ্গক্ষেত্র দেখায়। বিবাহ, দস্তাবেজ, ঔষধ, ৰিপোৰ্ট বা পিকনি অনুযায়ী ফিল্টাৰ সংকীর্ণ কৰে।",
    "help.answer.documents": "ৰোগীয়ে পেণ্টিং ফটো, ল্যাব ৰিপোৰ্ট আৰু ডিচাৰ্জ সাৰাংশ আপলোড বা স্কেন কৰিব পাৰে। OCR টেক্সট পঢ়ে আৰু কেୟাৰ লিংকে ঔষধ নাম, মাত্রা, তাৰিখ আৰু হস্পিতাল ক্ষেত্র উদ্ধৃত লৈ স্বাস্থ্য ৰেকৰ্ডত যোগ কৰে।",
    "help.answer.language": "কেୟাৰ লিংকে ইংৰাজী, হিন্দী আৰু উর্দু সৈতে বহুতো ভাষা সমর্থন কৰে। উর্দু লেয়া-আউট সোঁ-বাওঁ (RTL) হোৱা। স্বাগত পৃষ্ঠা ভাষা স্ক্রিনৰ পৰা যিকোনো সময়ত ভাষা সলাব পাৰে।",
    "help.answer.theme": "উপলব্ধতা স্ক্রিনে আপোনাক থিম ৰং বাছিবলৈ দিয়ে — বগা, নীলা, সেউজীয়া, গোলাপী, সোণালী বা ক'লা। সম্পূৰ্ণ এপটো তৃষ্ণা সোনাক আপডেট। স্বাগত পৃষ্ঠা উপলব্ধতা বুটামৰ পৰা এইটো পাব।",
    "help.answer.ai": "মই কেୟাৰ লিংক সহায়ক। কেୟাৰ লিংক হস্পিতাল আৰু ক্লিনিকৰ বাবে এটা AI-সহায়িত, সন্দৰ্ভ-প্রমাণিত ক্লিনিকেল ইতিহাস আৰু কেছ লোয়া এপ। মূল অংশ: ৰোগী পঞ্জীয়ন আৰু প্ৰফাইল, হস্পিতাল-দেৱা প্ৰমাণপত্ৰ সৈতে ডাক্তৰ লগইন, মেডিকিঅস্ক স্বয়ং-সেৱা কেছ লোয়া টার্মিনাল, ৰেড ফ্ল্যাগ চিনাক্ত সৈতে AI-উৎপন্ন ক্লিনিকেল সাৰাংশ, দস্তাবেজ OCR, স্বাস্থ্য টাইমলাইন, ভাষা/উপলব্ধতা থিম আৰু ABDM/সন্মতি-প্ৰস্তুত ডিজাইন। এইবোৰৰ যি কোনো সম্বন্ধে সুধক।",
    "help.suggest.1": "এই এপটোৱে কি কৰে?",
    "help.suggest.2": "ৰোগীয়ে কেনেকৈ পঞ্জীয়ন হয়?",
